	private const string Script = "const BOX_W = 250, GAP_X = 22, GAP_Y = 76, LINE = 19, PER_LINE = 26;\r\nconst COLOURS = ['#F0B285','#8FB8DE','#C2D0A8','#E0A6C8','#D9C48A','#9FD3C7'];\r\nconst sv = document.getElementById('sv'), wrap = document.getElementById('wrap'), tip = document.getElementById('tip');\r\nlet view = { x: 0, y: 0, k: 1 };\r\n\r\nfunction walk(n, f) { f(n); (n.kids || []).forEach(k => walk(k, f)); }\r\nwalk(TREE, n => { n.open = true; });\r\n\r\nconst byId = {};\r\nlet id = 0;\r\n(function index(n, parent) { n.parent = parent; n.id = id++; byId[n.id] = n; (n.kids || []).forEach(k => index(k, n)); })(TREE, null);\r\n\r\n// <b>A label is wrapped, and the box grows to hold it.</b> A question in Arabic runs longer\r\n// than any box a picture of forty nodes can afford to be, and a box that clips its own\r\n// question is worse than no box: the owner could not read what a branch asked.\r\nfunction lines(n) {\r\n    if (n.lines) return n.lines;\r\n    const words = String(n.label).split(/\\s+/);\r\n    const out = [];\r\n    let row = '';\r\n    for (const w of words) {\r\n        if (row && (row + ' ' + w).length > PER_LINE) { out.push(row); row = w; }\r\n        else { row = row ? row + ' ' + w : w; }\r\n    }\r\n    if (row) out.push(row);\r\n    n.lines = out.length ? out : [''];\r\n    return n.lines;\r\n}\r\n\r\nfunction height(n) { return 16 + lines(n).length * LINE + (n.sub ? 16 : 0); }\r\n\r\n// Rows are as tall as the tallest box on them, so nothing overlaps whatever a label needs.\r\nlet rowTop = [];\r\nfunction measure(n, depth) {\r\n    rowTop[depth] = Math.max(rowTop[depth] || 0, height(n));\r\n    if (n.open) (n.kids || []).forEach(k => measure(k, depth + 1));\r\n}\r\n\r\n// Leaves take the next free column; a parent sits centred over its children. Enough for a\r\n// tree of boxes, and it stays right when a node is folded away.\r\nfunction layout(n, depth, cursor) {\r\n    n.y = rowTop.slice(0, depth).reduce((a, b) => a + b + GAP_Y, 0);\r\n    const kids = n.open ? (n.kids || []) : [];\r\n    if (kids.length === 0) { n.x = cursor.x; cursor.x += BOX_W + GAP_X; return; }\r\n    kids.forEach(k => layout(k, depth + 1, cursor));\r\n    n.x = (kids[0].x + kids[kids.length - 1].x) / 2;\r\n}\r\n\r\nfunction shown(n) { return n.parent ? (n.parent.open && shown(n.parent)) : true; }\r\n\r\nfunction draw() {\r\n    rowTop = [];\r\n    measure(TREE, 0);\r\n    layout(TREE, 0, { x: 0 });\r\n    const parts = [];\r\n    let maxX = 0, maxY = 0;\r\n\r\n    const tint = new Map();\r\n    let colour = 0;\r\n    (TREE.kids || []).forEach(b => { const c = COLOURS[colour++ % COLOURS.length]; walk(b, n => tint.set(n, c)); });\r\n\r\n    walk(TREE, n => {\r\n        if (n !== TREE && !shown(n)) return;\r\n        maxX = Math.max(maxX, n.x + BOX_W);\r\n        maxY = Math.max(maxY, n.y + height(n) + 20);\r\n    });\r\n\r\n    // Links first, so boxes sit on top of them.\r\n    walk(TREE, n => {\r\n        if (!n.open || (n !== TREE && !shown(n))) return;\r\n        (n.kids || []).forEach(k => link(parts, n, k, tint.get(k) || '#F0B285'));\r\n    });\r\n\r\n    walk(TREE, n => { if (n === TREE || shown(n)) box(parts, n, tint.get(n) || '#F0B285'); });\r\n\r\n    sv.innerHTML = `<g id=\"cam\">${parts.join('')}</g>`;\r\n    sv.querySelectorAll('[data-i]').forEach(el => {\r\n        el.style.cursor = 'pointer';\r\n        el.addEventListener('click', ev => { ev.stopPropagation(); const n = byId[el.dataset.i]; n.open = !n.open; draw(); });\r\n        el.addEventListener('mousemove', ev => show(byId[el.dataset.i], ev));\r\n        el.addEventListener('mouseleave', () => { tip.style.display = 'none'; });\r\n    });\r\n    apply();\r\n    return { maxX, maxY };\r\n}\r\n\r\nfunction link(parts, a, b, colour) {\r\n    const x1 = a.x + BOX_W / 2, y1 = a.y + height(a), x2 = b.x + BOX_W / 2, y2 = b.y;\r\n    const m = (y1 + y2) / 2;\r\n    parts.push(`<path d=\"M${x1},${y1} C${x1},${m} ${x2},${m} ${x2},${y2}\" fill=\"none\" stroke=\"${colour}\" stroke-width=\"2\" opacity=\".65\"/>`);\r\n}\r\n\r\n// <b>The filter the owner asked for instead of a second tree.</b> It never hides a node —\r\n// a hidden node is a node whose repair you forget. It dims the ones with no game of the\r\n// chosen kind and writes, on the ones that have some, how many.\r\nlet KFILTER = '';\r\n\r\nfunction matching(n) {\r\n    if (!KFILTER) { return null; }\r\n    return (n.games || []).filter(g => KIND[g] === KFILTER).length;\r\n}\r\n\r\nfunction box(parts, n, colour) {\r\n    const hits = matching(n);\r\n    const faded = hits === 0 ? ' opacity=\".22\"' : '';\r\n    const fill = n.kind === 'unknown' ? '#F2A69A'\r\n        : n.kind === 'ask' ? '#3A3226'\r\n        : n.kind === 'todo' ? '#2D261C' : colour;\r\n    const ink = (n.kind === 'ask' || n.kind === 'todo') ? '#B0A595' : '#231D15';\r\n    const dash = (n.kind === 'todo') ? ' stroke-dasharray=\"5 4\"' : '';\r\n    const folded = (n.kids || []).length && !n.open;\r\n    const rows = lines(n), h = height(n);\r\n    const text = rows.map((row, i) =>\r\n        `<text x=\"${BOX_W / 2}\" y=\"${14 + (i + 1) * LINE - 5}\" text-anchor=\"middle\" fill=\"${ink}\"\r\n               font-size=\"15\" font-weight=\"600\" font-family=\"Segoe UI,Tahoma,sans-serif\">${esc(row)}</text>`).join('');\r\n\r\n    parts.push(`<g data-i=\"${n.id}\" transform=\"translate(${n.x},${n.y})\"${faded}>\r\n      <rect width=\"${BOX_W}\" height=\"${h}\" rx=\"12\" fill=\"${fill}\" stroke=\"${colour}\" stroke-width=\"1.5\"${dash}/>\r\n      ${text}\r\n      ${n.sub ? `<text x=\"${BOX_W / 2}\" y=\"${h - 7}\" text-anchor=\"middle\" fill=\"${ink}\" opacity=\".8\" font-size=\"12\"\r\n            font-family=\"Segoe UI,Tahoma,sans-serif\">${esc(n.sub)}</text>` : ''}\r\n      ${folded ? `<circle cx=\"${BOX_W / 2}\" cy=\"${h + 9}\" r=\"8\" fill=\"#2D261C\" stroke=\"${colour}\"/>\r\n                  <text x=\"${BOX_W / 2}\" y=\"${h + 13}\" text-anchor=\"middle\" fill=\"${colour}\" font-size=\"13\">+</text>` : ''}\r\n      ${hits ? `<rect x=\"6\" y=\"6\" width=\"34\" height=\"18\" rx=\"6\" fill=\"#231D15\" stroke=\"${colour}\"/>\r\n                <text x=\"23\" y=\"19\" text-anchor=\"middle\" fill=\"${colour}\" font-size=\"12\"\r\n                      font-family=\"Segoe UI,Tahoma,sans-serif\">${hits}</text>` : ''}\r\n    </g>`);\r\n}\r\n\r\nfunction esc(s) { return String(s).replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c])); }\r\n\r\nfunction show(n, ev) {\r\n    if (!n.games || !n.games.length) { tip.style.display = 'none'; return; }\r\n    const some = n.games.slice(0, 24);\r\n    // <b>The acceptance measure first, because it is the point</b> (D-192): a leaf says\r\n    // how a game is translated, and this says how we know it worked. A leaf with none\r\n    // says that too — what is missing has to be as visible as what is there.\r\n    const accept = (n.kids && n.kids.length) ? ''\r\n        : `<div style=\"margin:6px 0 8px;padding:6px 8px;border-radius:6px;background:#231D15\">\r\n             <span style=\"opacity:.65\">قياس\u064f القبول:</span>\r\n             ${n.accept ? esc(n.accept) : '<span style=\"color:#F2A69A\">\ud83d\udd34 لا قياس\u064e لهذه الورقة</span>'}\r\n           </div>`;\r\n    tip.innerHTML = `<b>${esc(n.label)}</b> — ${n.n} لعبة<br>` + accept\r\n                  + some.map(g => esc(g) + (KIND[g] ? `<span class=\"k\">${esc(KIND[g])}</span>` : '')).join('<br>')\r\n                  + (n.games.length > some.length ? `<br><span style=\"opacity:.6\">… و${n.games.length - some.length} غيرها</span>` : '');\r\n    const r = wrap.getBoundingClientRect();\r\n    tip.style.display = 'block';\r\n    tip.style.left = Math.min(ev.clientX - r.left + 14, r.width - 360) + 'px';\r\n    tip.style.top = (ev.clientY - r.top + 14) + 'px';\r\n}\r\n\r\nfunction apply() {\r\n    const cam = document.getElementById('cam');\r\n    if (cam) cam.setAttribute('transform', `translate(${view.x},${view.y}) scale(${view.k})`);\r\n}\r\n\r\nfunction fit() {\r\n    const b = draw();\r\n    const r = wrap.getBoundingClientRect();\r\n    view.k = Math.min(1.1, Math.min((r.width - 40) / Math.max(b.maxX, 1), (r.height - 40) / Math.max(b.maxY, 1)));\r\n    view.x = (r.width - b.maxX * view.k) / 2;\r\n    view.y = 20;\r\n    apply();\r\n}\r\n\r\nlet drag = null;\r\nwrap.addEventListener('mousedown', e => { drag = { x: e.clientX - view.x, y: e.clientY - view.y }; wrap.style.cursor = 'grabbing'; });\r\nwindow.addEventListener('mouseup', () => { drag = null; wrap.style.cursor = 'grab'; });\r\nwindow.addEventListener('mousemove', e => { if (!drag) return; view.x = e.clientX - drag.x; view.y = e.clientY - drag.y; apply(); });\r\nwrap.addEventListener('wheel', e => {\r\n    e.preventDefault();\r\n    const r = wrap.getBoundingClientRect(), mx = e.clientX - r.left, my = e.clientY - r.top;\r\n    const k = Math.max(0.08, Math.min(3, view.k * (e.deltaY < 0 ? 1.12 : 1 / 1.12)));\r\n    view.x = mx - (mx - view.x) * (k / view.k);\r\n    view.y = my - (my - view.y) * (k / view.k);\r\n    view.k = k; apply();\r\n}, { passive: false });\r\nfor (const [id, kind] of [['kAll', ''], ['kMono', 'Mono'], ['kIl2', 'IL2CPP']]) {\r\n    const button = document.getElementById(id);\r\n    if (!button) { continue; }\r\n    button.addEventListener('click', () => {\r\n        KFILTER = kind;\r\n        for (const other of ['kAll', 'kMono', 'kIl2']) {\r\n            document.getElementById(other).classList.toggle('on', other === id);\r\n        }\r\n        draw();\r\n    });\r\n}\r\n\r\ndocument.getElementById('fit').addEventListener('click', fit);\r\nfit();";

